const fs = require("fs");
const links = [];
const walk = d => fs.readdirSync(d, {withFileTypes:true}).forEach(e => {
  const p = d + "/" + e.name;
  if (e.isDirectory() && !["node_modules",".git"].includes(e.name)) walk(p);
  else if (e.isFile() && e.name.endsWith("spec.md")) {
    const text = fs.readFileSync(p, "utf8");
    for (const m of text.matchAll(/\[validated by:? ?([^]]*)\]\((\.\.[^)]*?)#L(\d+)\)/g)) links.push({spec: p, title: m[1], path: m[2], line: +m[3]});
